const paths={pin:'<path d="M12 17v5M5 17h14v-2l-3-3V5l1-1V3H7v1l1 1v7l-3 3z"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 3M4 15l2 3a7 7 0 0 0 12-1"/>',checks:'<path d="m3 6 2 2 4-4M13 6h8M3 16l2 2 4-4M13 16h8"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',down:'<path d="m6 9 6 6 6-6"/>',right:'<path d="m9 6 6 6-6 6"/>',back:'<path d="m15 6-6 6 6 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18"/><ellipse cx="12" cy="12" rx="4" ry="9"/>',book:'<path d="M12 7v14M3 3h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5v16h-5a4 4 0 0 0-4 2 4 4 0 0 0-4-2H3z"/>',review:'<circle cx="6" cy="3" r="2"/><path d="M6 5v14M18 6a4 4 0 0 0-4-4m4 4v13"/><circle cx="6" cy="21" r="2"/><circle cx="18" cy="21" r="2"/>'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]}</svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const bootstrap=['empty','discovering','discovered'].includes(document.body.dataset.state);let populated=document.body.dataset.state==='discovered';
let state=document.body.dataset.state, expanded=['details','permission','timeout','organized','discovered'].includes(state), timer;
if(state.startsWith('mobile'))state='complete';
const renderPin=(title,host,kind,key)=>`<button class="pin" data-dc-id="pin-${key}" title="Prototype link; does not open a live resource"><span>${icon(kind)}</span><span class="pin-copy"><span class="pin-title">${title}</span><span class="pin-host">${host}</span></span></button>`;
function render(){if(state==='settings')return;const running=['running','discovering'].includes(state),done=['complete','details'].includes(state),partial=state==='partial',limited=['permission','timeout'].includes(state);document.querySelector('[data-refresh]').disabled=running;document.querySelector('[data-refresh]').innerHTML=icon('refresh',running?'spin':'');const status=document.querySelector('.status');status.hidden=['idle','empty'].includes(state);let title=state==='discovered'?'3 added':state==='permission'?'Refresh needs permission':state==='timeout'?'Refresh timed out':state==='organized'?'Sections reorganized':running?(bootstrap&&!populated?'Finding useful pins…':'Refreshing pins…'):done?'2 updated · 1 removed':partial?'1 updated · 2 unverified':state==='canceled'?'Refresh canceled':'Pins are up to date';status.innerHTML=`<div class="status-line" data-dc-id="refresh-status"><button class="status-main" data-toggle ${running?'disabled':''} aria-expanded="${expanded}" data-dc-id="refresh-result-toggle">${icon(running?'refresh':(partial||limited)?'info':'check',running?'spin':(partial||limited)?'warn':'ok')}<span>${title}</span>${!running?icon(expanded?'down':'right'):''}</button>${running?'<button class="quiet" data-cancel data-dc-id="cancel-refresh">Cancel</button>':'<button class="icon-button" data-dismiss title="Dismiss result" aria-label="Dismiss refresh result" data-dc-id="dismiss-result">'+icon('close')+'</button>'}</div>`;
if(expanded&&!running){const details=state==='discovered'?'<p><strong>Added · Development preview</strong>Current preview shared in “Mobile navigation”.</p><p><strong>Added · Review changes</strong>Open review linked in “Navigation implementation”.</p><p><strong>Added · Interaction demo</strong>Demo produced in “Mobile navigation”.</p><p>Recent conversations provided enough context. No repository inspection was needed.</p>':state==='permission'?'<p><strong>Stopped at a permission request</strong>The worker needed approval to inspect the review link. No permission was granted.</p><p><strong>3 pins unverified</strong>Kept these pins unchanged.</p><p><strong>Updated · Project guide</strong>A documentation URL was corrected before stopping.</p>':state==='timeout'?'<p><strong>Stopped after 5 minutes</strong>The worker reached the refresh time limit.</p><p><strong>2 pins unverified</strong>Kept these pins unchanged.</p><p><strong>Updated · Project guide</strong>Kept the URL correction already applied.</p>':state==='organized'?'<p><strong>Renamed · Preview → Environments</strong>A clearer name for the existing group.</p><p><strong>Removed · Archived</strong>Removed an empty section.</p><p>All 4 pins retained. No new notifications.</p>':done?'<p><strong>Updated · Development preview</strong>Points to the current preview URL.</p><p><strong>Updated · Project guide</strong>Replaced an outdated documentation path.</p><p><strong>Removed · Review #42</strong>The pull request was merged.</p>':partial?'<p><strong>Updated · Project guide</strong>Replaced an outdated documentation path.</p><p><strong>Unverified · Development preview</strong>Did not respond. Kept the pin.</p><p><strong>Unverified · Review changes</strong>Sign-in required. Kept the pin.</p>':state==='canceled'?'<p>No pin changes were applied before cancellation.</p>':'<p>Reviewed 4 pins. No changes were needed.</p>';status.innerHTML+=`<div class="result-details" data-dc-id="refresh-details">${details}<p class="meta">${state==='canceled'?'Canceled':'Just now'} · Refresh profile</p></div>`}
document.querySelector('.pin-list').innerHTML=renderPin('Project home','example.test','globe','home')+'<section class="group" data-dc-id="group-preview"><h2 class="section-title">'+(state==='organized'?'Environments':'Preview')+'</h2>'+renderPin('Development preview','preview.example.test','globe','preview')+'</section><section class="group" data-dc-id="group-resources"><h2 class="section-title">Resources</h2>'+renderPin('Project guide','docs.example.test','book','guide')+renderPin('Review changes','github.com','review','review')+(running?renderPin('Review #42','github.com','review','old-review'):'')+'</section>';
if(bootstrap){document.querySelector('.pin-list').innerHTML=populated?'<section class="group" data-dc-id="group-active"><h2 class="section-title">Active work</h2>'+renderPin('Development preview','preview.example.test','globe','preview')+renderPin('Review changes','github.com','review','review')+renderPin('Interaction demo','demo.example.test','globe','demo')+'</section>':'<div class="empty-state" data-dc-id="empty-message">No pins yet</div>';}
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-refresh')){state='running';expanded=false;render();clearTimeout(timer);timer=setTimeout(()=>{state=bootstrap?'discovered':'complete';if(bootstrap)populated=true;render()},1600)}else if(b.hasAttribute('data-toggle')){expanded=!expanded;render()}else if(b.hasAttribute('data-dismiss')){state='idle';expanded=false;render()}else if(b.hasAttribute('data-cancel')){clearTimeout(timer);state='canceled';expanded=false;render()}else if(b.hasAttribute('data-demo-complete')){clearTimeout(timer);state='complete';expanded=false;render()}else if(b.hasAttribute('data-demo-partial')){state='partial';expanded=true;render()}});
document.querySelector('select')?.addEventListener('change',()=>{document.querySelector('[data-save-state]').textContent='Saved for this host · Prototype only'});render();
